"""Pin and adapt the MIT Apollo4 timer engine for a strict Apollo510 Timer14 adapter."""
import hashlib
from pathlib import Path
SHA='45602dadf7491056d06fa9cc231af711a07c4b9d0b53d2406cfee180a7085eff'
def load_engine(simulator,timer7_pwm=False):
 root=Path(simulator)/'timer14-research-01';data=(root/'AmbiqApollo4_Timer.cs').read_bytes()
 if hashlib.sha256(data).hexdigest()!=SHA:raise ValueError('Unreviewed timer engine')
 if hashlib.sha256((root/'MIT.txt').read_bytes()).hexdigest()!='8f71659370c5268d9a1dc962a46232540e8fca63462586d8efaa95aab492a208':raise ValueError('Timer license differs')
 text=data.decode()
 def replace(old,new,count=1):
  nonlocal text
  if text.count(old)!=count:raise ValueError('Timer engine adaptation differs: '+old[:70])
  text=text.replace(old,new)
 replace('AmbiqApollo4_Timer','BlackwallApolloTimerEngine',2)
 replace('Registers.GlobalEnable.Define(this, 0x7ff)','Registers.GlobalEnable.Define(this, 0xffff)')
 replace('private const long LFRCFrequency = 1000;','private const long LFRCFrequency = 900;')
 replace('            case ClockSelect.HFRCDiv16:','            case (ClockSelect)0: // Internal inactive reset clock; not exposed as an enabled adapter profile.\n                frequency = HFRCFrequency;\n                divider = 4;\n                break;\n            case ClockSelect.HFRCDiv16:')
 replace('                            case FunctionSelect.Continous:','                            case FunctionSelect.Edge: // Adapter restricts primary comparator to UINT32_MAX.\n                            case FunctionSelect.Continous:')
 replace('WithEnumField<DoubleWordRegister, ClockSelect>(8, 8,','WithEnumField<DoubleWordRegister, ClockSelect>(8, 9,')
 replace('.WithEnumField(16, 2, out triggerMode[index]','.WithEnumField(17, 2, out triggerMode[index]')
 replace('.WithReservedBits(18, 6)','.WithReservedBits(19, 5)')
 replace('.WithEnumField(8, 8, out triggerSource[index]','.WithEnumField(8, 9, out triggerSource[index]')
 replace('.WithReservedBits(16, 16)','.WithReservedBits(17, 15)')
 # Exclusive wrap period prevents zero-period rescheduling when compare is UINT32_MAX.
 # Renode clears fractional residue at events; exact nominal endpoints can lag by one tick.
 replace("limit: 0xFFFFFFFF,", "limit: 0x100000000UL,", 2)
 replace('compare: 0xFFFFFFFF, enabled: false);','compare: 0xFFFFFFFF, enabled: false, eventEnabled: true);',2)
 replace('                Enabled = false;\n                Compare0Event = false;\n                Compare1Event = false;','                Enabled = false;\n                Value = 0;Compare0 = Compare1 = 0;\n                Compare0Interrupt = Compare1Interrupt = false;OneShot = false;\n                Compare0Event = false;\n                Compare1Event = false;')
 replace('                    Value = 0;\n                    compare0Timer.Enabled = value;','                    compare0Timer.Enabled = value;')
 for n in [0,1]:
  replace(f'get => compare{n}Timer.EventEnabled;\n                set => compare{n}Timer.EventEnabled = value;',f'get => compare{n}Interrupt;\n                set => compare{n}Interrupt = value;')
 replace('            private readonly ComparingTimer compare0Timer;','            private bool compare0Interrupt,compare1Interrupt;\n            private readonly ComparingTimer compare0Timer;')
 begin=text.index('using System;');end=text.index('namespace Antmicro.Renode.Peripherals.Timers');imports=text[begin:end];text=text[:begin]+text[end:]
 replace('namespace Antmicro.Renode.Peripherals.Timers\n{\n','namespace Antmicro.Renode.Peripherals.Timers\n{\n'+imports)
 if timer7_pwm:
  # Preserve legacy generated bytes unless this explicit candidate is selected.
  replace('                Connections[i].Unset();','                Connections[i].Unset();\n                if(i == 7) { internalTimers[i].Frequency = HFRCFrequency; internalTimers[i].Divider = 4; }')
  replace('                            switch(value)','                            internalTimers[index].Pwm = value == FunctionSelect.PWM;\n                            switch(value)')
  replace('                            case FunctionSelect.Upcount:','                            case FunctionSelect.PWM:\n                                internalTimers[index].OneShot = false;\n                                break;\n                            case FunctionSelect.Upcount:')
  replace('                    Compare0Event = true;\n                    CompareReached();','                    Compare0Event = true;\n                    CompareReached(true);')
  replace('                    Compare1Event = true;\n                    CompareReached();','                    Compare1Event = true;\n                    CompareReached(false);')
  replace('            public bool OneShot { get; set; }','            public bool OneShot { get; set; }\n            public bool Pwm { get; set; }')
  replace('Compare0Interrupt = Compare1Interrupt = false;OneShot = false;','Compare0Interrupt = Compare1Interrupt = false;OneShot = Pwm = false;')
  replace('            private void CompareReached()\n            {\n                OnCompare?.Invoke();\n\n                if(OneShot)','            private void CompareReached(bool primary)\n            {\n                if(Pwm && primary) Value = 0;\n                OnCompare?.Invoke();\n\n                if(!Pwm && OneShot)')
 return text

if __name__=='__main__':
 import argparse
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('simulator',type=Path);p.add_argument('output',type=Path);p.add_argument('--timer7-pwm',action='store_true');a=p.parse_args()
 a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(load_engine(a.simulator,timer7_pwm=a.timer7_pwm))
 print(hashlib.sha256(a.output.read_bytes()).hexdigest())
